#pragma once

static const char JRBOT_V16_JS[] =
"(function(){'use strict';\n"
"const q=id=>document.getElementById(id);\n"
"const sleep=ms=>new Promise(r=>setTimeout(r,ms));\n"
"let v16CamUrl=null,live=false,liveSeq=0,liveFrames=0,liveStarted=0;\n"
"let listenWanted=false,listenRunning=false,listenGeneration=0,listenCurrent=null,listenCtx=null,listenNext=0;\n"
"let talkRequested=false,talkActive=false,talkCtx=null,talkStream=null,talkSource=null,talkNode=null,talkGain=null,talkSamples=[],talkQueue=[],talkSending=false,talkDrops=0,resumeListenAfterTalk=false;\n"
"function feedback(t,e){const x=q('feedback');if(!x)return;x.textContent=t;x.className='feedback'+(e?' err':'');}\n"
"function setState(t){const x=q('v16-state');if(x)x.textContent=t;}\n"
"function injectStyle(){const s=document.createElement('style');s.textContent='.v16-tools{margin-top:10px;padding-top:10px;border-top:1px solid #29415f}.v16-tools select{min-width:135px}.v16-livebar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:9px}.v16-meta{color:#9fb1ca;font-size:12px;margin-top:7px}.v16-ptt{width:100%;margin-top:10px;font-weight:700;touch-action:none;user-select:none;-webkit-user-select:none}.v16-ptt.active{background:#8b3346;border-color:#db6b7d}.v16-listen.active{background:#214c3c;border-color:#63d99b}';document.head.appendChild(s);}\n"
"function qualityValue(){return Number(q('v16-photo-quality').value||12);}\n"
"function liveQuality(){const s=q('v16-live-size').value;return s==='svga'?16:s==='vga'?14:16;}\n"
"function setCameraBlob(blob,label){if(v16CamUrl)URL.revokeObjectURL(v16CamUrl);v16CamUrl=URL.createObjectURL(blob);const img=q('camera');img.src=v16CamUrl;img.hidden=false;const save=q('cam-save');save.href=v16CamUrl;save.hidden=false;save.download='jrbot-camera-'+Date.now()+'.jpg';if(label)feedback(label);}\n"
"async function capturePhoto(){if(live){feedback('Pare o modo ao vivo para capturar uma foto em alta resolução.',true);return;}const size=q('v16-photo-size').value,quality=qualityValue();const btn=q('cam-btn');btn.disabled=true;try{feedback('Capturando foto '+size+'...');const r=await fetch('/capture?size='+encodeURIComponent(size)+'&quality='+quality+'&t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();setCameraBlob(b,'Foto atualizada. '+(r.headers.get('X-JrBot-Width')||'?')+'x'+(r.headers.get('X-JrBot-Height')||'?')+', '+Math.round(b.size/1024)+' KB.');btn.textContent='Atualizar foto';}catch(e){feedback('Erro na câmera: '+e.message,true);}finally{btn.disabled=false;}}\n"
"async function liveLoop(seq){while(live&&seq===liveSeq){try{const size=q('v16-live-size').value,quality=liveQuality();const t0=performance.now();const r=await fetch('/capture?live=1&size='+encodeURIComponent(size)+'&quality='+quality+'&t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();if(!live||seq!==liveSeq)break;setCameraBlob(b,null);liveFrames++;const elapsed=(performance.now()-liveStarted)/1000;const fps=elapsed>0?liveFrames/elapsed:0;const frameMs=performance.now()-t0;q('v16-live-meta').textContent='Ao vivo: '+(r.headers.get('X-JrBot-Width')||'?')+'x'+(r.headers.get('X-JrBot-Height')||'?')+' · '+fps.toFixed(1)+' FPS médio · '+Math.round(b.size/1024)+' KB/quadro · '+Math.round(frameMs)+' ms';await sleep(20);}catch(e){if(live){setState('Falha no vídeo ao vivo: '+e.message);await sleep(500);}}}}\n"
"function startLive(){if(live)return;live=true;liveSeq++;liveFrames=0;liveStarted=performance.now();q('v16-live').textContent='Parar ao vivo';q('v16-live').classList.add('active');setState('Câmera ao vivo iniciada.');liveLoop(liveSeq);}\n"
"function stopLive(){live=false;liveSeq++;q('v16-live').textContent='Iniciar ao vivo';q('v16-live').classList.remove('active');setState('Câmera ao vivo parada.');}\n"
"function toggleLive(){if(live)stopLive();else startLive();}\n"
"function ensureListenContext(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('AudioContext indisponível.');if(!listenCtx)listenCtx=new AC();return listenCtx.resume().then(()=>listenCtx);}\n"
"async function playWavBlob(blob){const ctx=await ensureListenContext();const ab=await blob.arrayBuffer();const decoded=await ctx.decodeAudioData(ab.slice(0));const src=ctx.createBufferSource();src.buffer=decoded;src.connect(ctx.destination);let when=Math.max(ctx.currentTime+0.03,listenNext);if(when-ctx.currentTime>1.4)when=ctx.currentTime+0.03;src.start(when);listenNext=when+decoded.duration;}\n"
"async function listenLoop(gen){listenRunning=true;setState('Ouvindo o ambiente pelo microfone do JrBot.');while(listenWanted&&!talkRequested&&gen===listenGeneration){try{const p=fetch('/mic-record?seconds=1&t='+Date.now(),{cache:'no-store'});listenCurrent=p;const r=await p;listenCurrent=null;if(!r.ok)throw Error(await r.text());const b=await r.blob();if(!listenWanted||talkRequested||gen!==listenGeneration)break;await playWavBlob(b);}catch(e){listenCurrent=null;if(listenWanted&&!talkRequested&&gen===listenGeneration){setState('Falha ouvindo o ambiente: '+e.message);await sleep(400);}}}listenRunning=false;}\n"
"async function startListen(){listenWanted=true;q('v16-listen').textContent='Parar de ouvir';q('v16-listen').classList.add('active');await ensureListenContext();listenGeneration++;listenLoop(listenGeneration);}\n"
"function stopListen(){listenWanted=false;listenGeneration++;q('v16-listen').textContent='Ouvir ambiente';q('v16-listen').classList.remove('active');listenNext=0;setState('Áudio ambiente parado.');}\n"
"async function toggleListen(){if(listenWanted)stopListen();else try{await startListen();}catch(e){feedback('Não foi possível iniciar o áudio: '+e.message,true);}}\n"
"function downsample(input,inputRate){if(inputRate===16000)return new Float32Array(input);const ratio=inputRate/16000,len=Math.max(1,Math.floor(input.length/ratio)),out=new Float32Array(len);for(let i=0;i<len;i++){const start=Math.floor(i*ratio),end=Math.max(start+1,Math.floor((i+1)*ratio));let sum=0,n=0;for(let j=start;j<end&&j<input.length;j++){sum+=input[j];n++;}out[i]=n?sum/n:0;}return out;}\n"
"function wavFromFloat(samples){const buf=new ArrayBuffer(44+samples.length*2),v=new DataView(buf);const ascii=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};ascii(0,'RIFF');v.setUint32(4,36+samples.length*2,true);ascii(8,'WAVE');ascii(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);ascii(36,'data');v.setUint32(40,samples.length*2,true);let o=44;for(let i=0;i<samples.length;i++,o+=2){let x=Math.max(-1,Math.min(1,samples[i]));v.setInt16(o,x<0?x*32768:x*32767,true);}return new Blob([buf],{type:'audio/wav'});}\n"
"function enqueueTalk(samples){if(!samples.length)return;if(talkQueue.length>=3){talkQueue.shift();talkDrops++;}talkQueue.push(wavFromFloat(samples));pumpTalk();}\n"
"async function pumpTalk(){if(talkSending)return;talkSending=true;while(talkQueue.length){const blob=talkQueue.shift();try{const r=await fetch('/audio',{method:'POST',headers:{'Content-Type':'audio/wav','X-JrBot-Audio':'1'},body:blob});if(!r.ok)throw Error(await r.text());}catch(e){setState('Falha enviando voz ao JrBot: '+e.message);break;}}talkSending=false;}\n"
"function flushTalkSamples(force){const target=12000;while(talkSamples.length>=target||(force&&talkSamples.length)){const count=talkSamples.length>=target?target:talkSamples.length;const out=new Float32Array(count);for(let i=0;i<count;i++)out[i]=talkSamples[i];talkSamples.splice(0,count);enqueueTalk(out);}}\n"
"async function startTalk(ev){if(ev){ev.preventDefault();try{ev.currentTarget.setPointerCapture(ev.pointerId);}catch(_){}}if(talkRequested)return;talkRequested=true;resumeListenAfterTalk=listenWanted;q('v16-ptt').classList.add('active');q('v16-ptt').textContent='FALANDO... SOLTE PARA OUVIR';setState('Preparando microfone do celular...');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(!talkRequested){stream.getTracks().forEach(t=>t.stop());return;}talkStream=stream;stopListen();if(listenCurrent){setState('Aguardando o último bloco do microfone do JrBot...');try{await listenCurrent;}catch(_){}}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('AudioContext indisponível.');talkCtx=new AC();await talkCtx.resume();talkSource=talkCtx.createMediaStreamSource(stream);talkNode=talkCtx.createScriptProcessor(4096,1,1);talkGain=talkCtx.createGain();talkGain.gain.value=0;talkNode.onaudioprocess=e=>{if(!talkRequested)return;const d=downsample(e.inputBuffer.getChannelData(0),talkCtx.sampleRate);for(let i=0;i<d.length;i++)talkSamples.push(d[i]);flushTalkSamples(false);};talkSource.connect(talkNode);talkNode.connect(talkGain);talkGain.connect(talkCtx.destination);talkActive=true;talkDrops=0;setState('Falando no JrBot. Solte o botão para voltar a ouvir.');}catch(e){talkRequested=false;talkActive=false;q('v16-ptt').classList.remove('active');q('v16-ptt').textContent='SEGURE PARA FALAR NO JRBOT';if(talkStream)talkStream.getTracks().forEach(t=>t.stop());talkStream=null;feedback('Microfone do celular indisponível: '+e.message,true);if(resumeListenAfterTalk)startListen();}}\n"
"async function stopTalk(ev){if(ev)ev.preventDefault();if(!talkRequested&&!talkActive)return;talkRequested=false;if(talkNode){talkNode.onaudioprocess=null;try{talkSource.disconnect();talkNode.disconnect();talkGain.disconnect();}catch(_){}}if(talkStream)talkStream.getTracks().forEach(t=>t.stop());talkStream=null;flushTalkSamples(true);talkSamples=[];talkActive=false;q('v16-ptt').classList.remove('active');q('v16-ptt').textContent='SEGURE PARA FALAR NO JRBOT';setState('Finalizando envio da fala...');while(talkSending||talkQueue.length)await sleep(40);setState(talkDrops?'Fala concluída. Blocos descartados por atraso: '+talkDrops+'.':'Fala concluída.');if(talkCtx){try{await talkCtx.close();}catch(_){}talkCtx=null;}if(resumeListenAfterTalk){resumeListenAfterTalk=false;try{await startListen();}catch(e){setState('Fala concluída; não foi possível retomar áudio: '+e.message);}}}\n"
"function build(){injectStyle();const sub=document.querySelector('.top .sub');if(sub)sub.textContent='V1 · painel local · JrBot_V1.6';const card=q('cam-btn')&&q('cam-btn').closest('.card');if(!card)return;const tools=document.createElement('div');tools.className='v16-tools';tools.innerHTML=\"<div class='row'><label>Foto</label><select id='v16-photo-size'><option value='vga'>640x480 · VGA</option><option value='svga'>800x600 · SVGA</option><option value='xga' selected>1024x768 · XGA</option><option value='hd'>1280x720 · HD</option><option value='uxga'>1600x1200 · UXGA</option></select><select id='v16-photo-quality'><option value='20'>Econômica</option><option value='12' selected>Normal</option><option value='8'>Alta</option></select></div><div class='v16-livebar'><label>Ao vivo</label><select id='v16-live-size'><option value='qvga'>320x240 · rápido</option><option value='vga' selected>640x480 · equilibrado</option><option value='svga'>800x600 · qualidade</option></select><button id='v16-live' class='grow'>Iniciar ao vivo</button></div><div id='v16-live-meta' class='v16-meta'>Live parado.</div><div class='v16-tools'><div class='row'><button id='v16-listen' class='v16-listen grow'>Ouvir ambiente</button></div><button id='v16-ptt' class='v16-ptt primary'>SEGURE PARA FALAR NO JRBOT</button><div id='v16-state' class='v16-meta'>Interfone parado. O modo é half-duplex: ao falar, a escuta pausa.</div></div>\";card.appendChild(tools);q('cam-btn').onclick=capturePhoto;q('v16-live').onclick=toggleLive;q('v16-listen').onclick=toggleListen;const p=q('v16-ptt');p.addEventListener('pointerdown',startTalk);p.addEventListener('pointerup',stopTalk);p.addEventListener('pointercancel',stopTalk);p.addEventListener('lostpointercapture',stopTalk);window.addEventListener('beforeunload',()=>{live=false;listenWanted=false;talkRequested=false;if(talkStream)talkStream.getTracks().forEach(t=>t.stop());});const foot=document.querySelector('.foot');if(foot)foot.textContent='Controle local do JrBot. Para microfone do navegador, use HTTPS. Interfone V1.6 em modo PTT half-duplex.';}\n"
"if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();\n"
"})();\n";
